import{decoder}from'tetris-fumen';import{boardFromFumenPage,highestOccupiedRow}from'./board.mjs';import{expandPattern,expandPatternCases,queuesForFinder}from'./pattern.mjs';import{queueCanSave,compileSaveExpression,savedMask}from'./saves.mjs';import{calculateSaveMinimals,encodeSaveMinimalFumen}from'./minimals-feature.mjs';import{fifthMinimalsPerSaves,encodeFifthCombined}from'./fifth.mjs';import{calculatePerSaveMinimals,encodePerSaveMinimals,resolvePerSaveTargetLines}from'./per-save-minimals.mjs';
export class UnsupportedClearHeightError extends Error{constructor(c){super(`unsupported clear height ${c}`);this.name='UnsupportedClearHeightError'}}export class UnsupportedBoardHeightError extends Error{constructor(h){super(`unsupported board height ${h}`);this.name='UnsupportedBoardHeightError'}}export class BoardExceedsClearHeightError extends Error{constructor(h,c){super(`board height ${h} exceeds clear ${c}`);this.name='BoardExceedsClearHeightError'}}
export function decodeAndValidate(sourceFumen,clear=4){if(!Number.isInteger(clear)||clear<2||clear>6)throw new UnsupportedClearHeightError(clear);const page=decoder.decode(sourceFumen)[0];if(!page)throw new Error('empty fumen');const hi=highestOccupiedRow(page);if(hi>=6)throw new UnsupportedBoardHeightError(hi+1);if(hi>=clear)throw new BoardExceedsClearHeightError(hi+1,clear);return{page,board:boardFromFumenPage(page,clear)}}
export function calculateChance({sourceFumen,pattern,clear=4,solver,useHold=true}){const{board}=decodeAndValidate(sourceFumen,clear),qs=expandPattern(pattern),solved=typeof solver.canPcMany==='function'?solver.canPcMany(board,qs,useHold):qs.map(q=>solver.canPc(board,q,useHold));let success=0;const failedQueues=[];for(let i=0;i<qs.length;i++){if(solved[i])success++;else failedQueues.push(qs[i])}return{total:qs.length,success,failed:failedQueues.length,failedQueues,percent:100*success/qs.length}}
export function calculateSaves({sourceFumen,pattern,wantedSave,clear=4,solver,useHold=true}){const{board}=decodeAndValidate(sourceFumen,clear),pathPattern=queuesForFinder(pattern),cases=expandPatternCases(pattern);for(const entry of cases)if(!entry.lastBag)throw new Error(`save analysis branch ${entry.branchIndex+1} does not end in a bag token`);let success=0;const failedQueues=[];if(clear>=5&&cases.length>=24&&typeof solver.enumeratePcPattern==='function'){const rows=solver.enumeratePcPattern(board,cases.map(x=>x.queue),useHold),table=compileSaveExpression(wantedSave),solved=new Uint8Array(cases.length);for(const solution of rows??[])for(const hit of solution.coverage){const entry=cases[hit.caseIndex];if(entry&&table[savedMask(entry.queue,solution,entry.lastBag)])solved[hit.caseIndex]=1}for(let i=0;i<cases.length;i++){if(solved[i])success++;else failedQueues.push(cases[i].queue)}}else{const cache=new Map();for(const entry of cases){let sols=cache.get(entry.queue);if(!sols){sols=solver.enumeratePc(board,entry.queue,useHold);cache.set(entry.queue,sols)}if(queueCanSave(entry.queue,sols,entry.lastBag,wantedSave))success++;else failedQueues.push(entry.queue)}}return{pathPattern,analysisPattern:pattern,total:cases.length,success,failed:failedQueues.length,failedQueues,percent:100*success/cases.length}}
export function calculateMinimalsFeature({sourceFumen,pattern,wantedSave,clear=4,solver,useHold=true}){decodeAndValidate(sourceFumen,clear);const c=calculateSaveMinimals({sourceFumen,analysisPattern:pattern,wantedSave,solver,useHold,height:clear});return{pathPattern:queuesForFinder(pattern),analysisPattern:pattern,total:c.queues.length,saveSuccess:c.saveSuccess,minimalCount:c.minimalCount,coverageCounts:c.coverageCounts,fumen:encodeSaveMinimalFumen(c)}}
export function calculateFifthFeature({sourceFumen,pattern,title='',clear=4,solver,useHold=true}){decodeAndValidate(sourceFumen,clear);if(clear!==4)throw new Error('5th is clear=4 only');const c=fifthMinimalsPerSaves({sourceFumen,analysisPattern:pattern,solver,useHold});const e=encodeFifthCombined({sourceFumen,title,calculation:c});return{total:c.queues.length,bestsave:c.bestsave,usages:c.usages,pageCounts:e.pageCounts,fumen:e.fumen}}
export function calculatePerSaveMinimalsFeature({sourceFumen,pattern,title='',targetLines,clear,solver,useHold=true,candidateLimit=16}){const resolved=resolvePerSaveTargetLines({targetLines,clear});decodeAndValidate(sourceFumen,resolved);const c=calculatePerSaveMinimals({sourceFumen,pattern,solver,useHold,targetLines:resolved,candidateLimit});const e=encodePerSaveMinimals({sourceFumen,title,calculation:c}),results={};for(const[p,r]of Object.entries(c.results))results[p]={piece:r.piece,success:r.success,pcSuccess:r.pcSuccess,total:r.total,saveRate:r.saveRate,guaranteed:r.guaranteed,minimalCount:r.minimalCount,coverageCounts:r.coverageCounts,playableOrderCount:r.playableOrderCount,label:r.label};return{targetLines:c.targetLines,occupiedCells:c.occupiedCells,remainingCells:c.remainingCells,piecesNeeded:c.piecesNeeded,expectedQueueLength:c.expectedQueueLength,total:c.total,pcSuccess:c.pcSuccess,pcRate:c.pcRate,results,pageCounts:e.pageCounts,fumen:e.fumen}}
